# Let's manually examine what changes in each case
inputs = ['buxz', 'zeyab', 'uuccg', 'zaauu', 'ucyyji']
outputs = ['yxuxz', 'zeyayx', 'uucyxgahbacyxgahbag', 'zaauu', 'ucyxgahbayyjba']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"\n{i}: '{inp}' -> '{outp}'")
        # Find differences character by character
        for j, (c_in, c_out) in enumerate(zip(inp, outp)):
            if c_in != c_out:
                print(f"  Position {j}: '{c_in}' -> '{c_out}'")
        # Check if one string is a substring of another
        if len(inp) < len(outp):
            # See if we can find what was inserted
            print(f"  Insertion detected (output longer)")
        elif len(inp) > len(outp):
            print(f"  Deletion detected (output shorter)")
        else:
            print(f"  Same length - substitution")
    else:
        print(f"\n{i}: '{inp}' -> '{outp}' (no change)")

